import { useCallback, useRef } from 'react'
import { DisplayFlexCCC, Row } from '../../../commonStyle/index.style'
import { Container, CustomText } from '../../../components'
import { AgentColorPallette } from '../../../configs/colorPallete'
import { useGlobalContextValue } from '../../../contextProvider/GlobalContext'
import { getCsDetailByAgentTag } from '../../../helpers/checkAgentTags'
import { ARROW_RIGHT_BLACK, CLAIM_REPORT, EMAIL_SVG_BOLD, WHATSAPP } from '../../../images'
import { LANG_STRINGS } from '../../../lang'
import {
  ClaimContactCardContainerStyle,
  ClaimContactItemCardStyle,
  ClaimCtaButtonStyle,
  ClaimDetailStyle,
  ClaimInfoStyle,
  RenderProcessCardStyle,
} from './index.style'
import { contactService } from '../../../helpers/utility'

function ClaimDetails() {
  const [{ getAgentDetailData = {} }] = useGlobalContextValue()
  const claimInfo = useRef([
    'Proses lapor klaim sampai survei klaim = 2 hari kerja.',
    'Proses survei klaim sampai SPK terbit = 2 hari kerja.',
    'SPK terbit sampai reparasi selesai = 2 hari kerja.',
  ])

  const renderProcessCard = useCallback((title) => {
    return <RenderProcessCardStyle>{title}</RenderProcessCardStyle>
  }, [])

  const renderClaimsInformation = useCallback(() => {
    return (
      <ClaimInfoStyle>
        <CustomText size="10px" color={AgentColorPallette.darkCharcoal}>
          {`*${LANG_STRINGS.remarksSubmitted}:`}
        </CustomText>
        <ol className="claim-info-list">
          {claimInfo.current.map((info, index) => (
            <li key={index}>
              <CustomText size="10px" color={AgentColorPallette.darkCharcoal}>
                {info}
              </CustomText>
            </li>
          ))}
        </ol>
      </ClaimInfoStyle>
    )
  }, [])

  const renderContactButton = useCallback((icon, title, contact, data) => {
    return (
      <ClaimContactItemCardStyle onClick={() => contactService(data)}>
        <img src={icon} alt={title} />
        <div>
          <CustomText
            textAlign="left"
            fontSize="12px"
            fontWeight={600}
            color={AgentColorPallette.regular}
            className="text-formating btn-txt"
          >
            {title}
          </CustomText>
          <CustomText
            textAlign="left"
            color={AgentColorPallette.regular}
            fontWeight={800}
            fontSize="12px"
            className="text-formating btn-text"
          >
            {contact}
          </CustomText>
        </div>
      </ClaimContactItemCardStyle>
    )
  }, [])

  const email = getCsDetailByAgentTag(getAgentDetailData).email
  const mobile = getCsDetailByAgentTag(getAgentDetailData).mobile

  return (
    <Container title={LANG_STRINGS.howToClaim} backBtnId="back_claims" bgColor="#FFC800">
      <ClaimDetailStyle paddingTop="60px">
        <CustomText
          size="14px"
          weight={800}
          color={AgentColorPallette.darkCharcoal}
          textAlign="center"
          top="8px"
        >
          {LANG_STRINGS.howToClaimTheEasier}
        </CustomText>
        <CustomText
          size="12px"
          color={AgentColorPallette.darkCharcoal}
          textAlign="center"
          top="8px"
          weight={600}
        >
          {LANG_STRINGS.nowYouCanClaim}
        </CustomText>
        <CustomText
          size="12px"
          color={AgentColorPallette.darkCharcoal}
          textAlign="center"
          bottom="16px"
          weight={600}
        >
          {LANG_STRINGS.contactUsNow}
        </CustomText>
        <img src={CLAIM_REPORT} alt="CLAIM REPORT" width="100%" />
        <CustomText
          size="12px"
          top="10px"
          bottom="16px"
          textAlign="center"
          color={AgentColorPallette.darkCharcoal}
        >
          {LANG_STRINGS.claimWithPortalClaim}
        </CustomText>

        <ClaimCtaButtonStyle>
          <CustomText
            size="14px"
            weight={800}
            color={AgentColorPallette.darkCharcoal}
            textAlign="center"
          >
            {LANG_STRINGS.claimViaPortalClaim}
          </CustomText>

          <a
            href={process.env.REACT_APP_CLAIM_PORTAL_URL}
            target="_blank"
            rel="noopener noreferrer"
            className="button"
          >
            <img src={ARROW_RIGHT_BLACK} alt="icon" />
          </a>
        </ClaimCtaButtonStyle>

        <CustomText
          size="12px"
          top="16px"
          bottom="16px"
          textAlign="center"
          weight={700}
          color={AgentColorPallette.darkCharcoal}
        >
          {LANG_STRINGS.claimMoreInformationByClick}
        </CustomText>

        <ClaimContactCardContainerStyle>
          {renderContactButton(EMAIL_SVG_BOLD, LANG_STRINGS.email, email, {
            type: 'email',
            displayData: email,
            email,
          })}
          {renderContactButton(WHATSAPP, LANG_STRINGS.whatsApp, mobile, {
            type: 'whatsapp',
            displayData: mobile,
            mobile,
            WAText: `hi tim klaim PasarPolis,\nsaya ${getAgentDetailData.name}, salah satu mitra di PasarPolis\ningin menanyakan/mengajukan klaim.\ntolong dibantu\nterima kasih`,
          })}
        </ClaimContactCardContainerStyle>

        <CustomText
          size="12px"
          top="16px"
          bottom="16px"
          textAlign="center"
          weight={700}
          color={AgentColorPallette.darkCharcoal}
        >
          {LANG_STRINGS.serviceHours}
        </CustomText>
        <div className="separator" />
      </ClaimDetailStyle>

      <ClaimDetailStyle paddingTop="16px" paddingBtm="25%">
        <CustomText
          size="14px"
          weight={800}
          bottom="16px"
          color={AgentColorPallette.darkCharcoal}
          textAlign="center"
        >
          {LANG_STRINGS.processGettingEasier}
        </CustomText>
        <Row align="stretch" justify="space-between" gap="8px">
          {renderProcessCard(LANG_STRINGS.reportCliam)}
          <DisplayFlexCCC>
            <i className="fas fa-arrow-right" />
          </DisplayFlexCCC>
          {renderProcessCard(LANG_STRINGS.surveyConducted)}
          <DisplayFlexCCC>
            <i className="fas fa-arrow-right" />
          </DisplayFlexCCC>
          {renderProcessCard(LANG_STRINGS.successfulClaim)}
        </Row>
        <ol className="claim-process-list">
          <li>{LANG_STRINGS.hassleFreeClaimProcess}</li>
          <li>{LANG_STRINGS.allClaimProcessByPasarPolis}</li>
          <li>{LANG_STRINGS.easilyTrackStatusOfYourClaim}</li>
        </ol>
      </ClaimDetailStyle>
    </Container>
  )
}

export default ClaimDetails
